    'aware.eyebrow':               { pt: 'Consciência Espacial', en: 'Space awareness' },
    'aware.themes':                { pt: 'Eixos da consciência espacial', en: 'Space awareness themes' },
    'aware.more':                  { pt: 'Saiba mais', en: 'Learn more' },
    'aware.less':                  { pt: 'Mostrar menos', en: 'Show less' },
    'aware.title.voyager':         { pt: 'Voyager 1', en: 'Voyager 1' },
    'aware.title.terra':           { pt: 'Órbita da Terra', en: 'Earth orbit' },
    'aware.title.lua':             { pt: 'Lua', en: 'Moon' },
    'aware.title.marte':           { pt: 'Marte', en: 'Mars' },
    'aware.theme.arqueologia':     { pt: 'Arqueologia', en: 'Archaeology' },
    'aware.theme.sustentabilidade':{ pt: 'Sustentabilidade', en: 'Sustainability' },
    'aware.theme.kessler':         { pt: 'Kessler', en: 'Kessler' },
    'aware.theme.legado':          { pt: 'Legado', en: 'Legacy' },
    'aware.theme.responsabilidade':{ pt: 'Responsabilidade', en: 'Responsibility' },
    'aware.theme.arqueologia.icon':{ pt: '🏛', en: '🏛' },
    'aware.theme.sustentabilidade.icon': { pt: '♻️', en: '♻️' },
    'aware.theme.kessler.icon':    { pt: '🌀', en: '🌀' },
